-- Website settings (only fields that are still empty).
update public.website_settings set
  tagline = coalesce(tagline, $v$Diversified investments. Integrated industries. Sustainable growth.$v$),
  seo_default_title = coalesce(seo_default_title, $v$VECTIS · Established 1956 · A Nigerian business group$v$),
  seo_default_description = coalesce(seo_default_description, $v$VECTIS is a diversified Nigerian business group, established in 1956, connecting capital, capability and opportunity across productive sectors.$v$)
where id = 1;

