-- Each company's sectors (the first listed is its main sector).
insert into public.company_sectors (company_id, sector_id, is_primary)
select c.id, s.id, true from public.companies c, public.sectors s
where c.slug = $v$vectis$v$ and s.slug = $v$investments$v$
  and not exists (select 1 from public.company_sectors x where x.company_id = c.id and x.sector_id = s.id)
  and (false or not exists (select 1 from public.company_sectors y where y.company_id = c.id and y.is_primary));
