-- Core website pages: filled and published, but only if still empty.
update public.pages set content = $v${"hero_heading": "Diversified investments. Integrated industries. Sustainable growth.", "hero_subheading": "Established in 1956, VECTIS is a Nigerian business group that connects capital, capability and opportunity across productive sectors, infrastructure and long-term value creation.", "intro_heading": "Built to connect capital, capability and opportunity", "intro_text": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS brings investment management, enterprise development, operating platforms and strategic partnerships into one integrated architecture."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio is designed as an integrated system, not a flat list of businesses. Five connected clusters work together across the value chain: from capital and assets to operations, markets and community impact."}]}]}, "highlights": [{"heading": "Investment and financial services", "text": "Investment platforms provide the group's strategic spine: capital allocation, financing solutions, shareholdings and portfolio governance."}, {"heading": "Energy and natural resources", "text": "Oil and gas, gas infrastructure, power generation, petroleum, and mining and minerals, including tin exploration and processing."}, {"heading": "Industry and productive enterprises", "text": "Manufacturing, processing, materials and productive enterprise development."}, {"heading": "Infrastructure and commercial services", "text": "Properties, construction, facility management, retail, telecommunications, information technology and media."}, {"heading": "Partnerships and social impact", "text": "Strategic alliances with serious partners, and community impact through the VECTIS Foundation."}], "cta_heading": "Built for serious partnerships", "cta_text": "VECTIS works with government institutions, domestic and international investors, development finance institutions, commercial banks, energy and industrial operators, technology providers, and joint-venture partners."}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$VECTIS · Established 1956 · A Nigerian business group$v$),
  seo_description = coalesce(seo_description, $v$Diversified investments, integrated industries and sustainable growth. A Nigerian business group, established in 1956.$v$),
  status = $v$published$v$
where page_key = $v$home$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "VECTIS is a diversified Nigerian business group, established in 1956. It brings investment management, enterprise development, operating platforms and strategic partnerships into one integrated architecture.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "One group, five connected business clusters"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio is designed as an integrated system, not a flat list of businesses. VECTIS is organised into five connected clusters:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Investment and financial services", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": the investment platforms that provide the group's strategic spine."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Energy and natural resources", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": oil, gas, power, petroleum, mining and minerals."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Industry and productive enterprises", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": manufacturing, processing, materials and enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Infrastructure and commercial services", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": places and access, digital reach and human capability."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Partnerships and social impact", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": strategic alliances and the VECTIS Foundation."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investing across the value chain"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "From opportunity identification and financing to operations, infrastructure, distribution and community outcomes, VECTIS is designed to connect capabilities across sectors. Its model runs from "}, {"type": "text", "text": "capital", "marks": [{"type": "bold"}]}, {"type": "text", "text": " to "}, {"type": "text", "text": "assets", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "operations", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "markets", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", and on to lasting "}, {"type": "text", "text": "impact", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Turning assets into enterprises"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Industry, infrastructure and commercial services turn assets into enterprises:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Places and access", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": properties, construction, facility management and retail."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Industrial platforms", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": manufacturing, processing, materials and productive enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Digital reach", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": telecommunications, information technology, media and communications."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Human capability", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": healthcare, pharmaceuticals, education and services."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Built for serious partnerships"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "VECTIS engages a broad range of counterparties across its investment platforms and operating clusters: government institutions, domestic and international investors, development finance institutions, commercial banks, energy and industrial operators, technology providers, and strategic joint-venture and project-development partners."}]}]}, "values": [{"heading": "Long-term value creation", "text": "We focus on productive sectors and infrastructure, building value that lasts."}, {"heading": "Integration", "text": "We connect capital, capability and opportunity across the value chain, rather than running a flat list of businesses."}, {"heading": "Discipline", "text": "We apply commercial discipline and robust oversight to every investment decision."}, {"heading": "Partnership", "text": "We build strategic alliances that give access to capabilities and markets."}, {"heading": "Community impact", "text": "Through the VECTIS Foundation, we extend enterprise into lasting community benefit."}]}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$About VECTIS$v$),
  seo_description = coalesce(seo_description, $v$A diversified Nigerian business group established in 1956, integrating investment, enterprise development, operations and partnerships.$v$),
  status = $v$published$v$
where page_key = $v$about$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "Founded in Nigeria and established in 1956, VECTIS has grown into a diversified business group spanning investment, energy and natural resources, industry, infrastructure and community impact.", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Today the group brings investment management, enterprise development, operating platforms and strategic partnerships into one integrated architecture, with a focus on productive sectors, infrastructure and long-term value creation."}]}]}, "timeline": [{"heading": "1956", "text": "VECTIS is established in Nigeria."}]}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$Corporate History · VECTIS$v$),
  seo_description = coalesce(seo_description, $v$VECTIS was founded in Nigeria and established in 1956.$v$),
  status = $v$published$v$
where page_key = $v$history$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "The VECTIS portfolio is designed as an integrated system, not a flat list of businesses. Investment platforms provide the group's strategic spine, and operating businesses carry its work into energy, natural resources, industry and beyond.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investment platforms"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Global Investment, Capital, Holdings, Integrated Resources and & Partners together provide strategic investment, capital allocation, financing, portfolio governance, enterprise development and partnership and project development."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Energy and natural resources"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Oil and Gas, Gas & Power, Petroleum and Tin Mines span upstream resources, infrastructure, processing, trading and downstream markets."}]}]}}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$Our Businesses · VECTIS$v$),
  seo_description = coalesce(seo_description, $v$The VECTIS businesses: investment platforms, energy and natural resources, and enterprises across fifteen sectors.$v$),
  status = $v$published$v$
where page_key = $v$businesses$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "Fifteen sectors, one disciplined investment mandate. VECTIS applies an integrated lens across productive sectors, financial services, infrastructure, enterprise development and social development.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investment platforms provide the strategic spine"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis Global Investment", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": strategic investments, capital allocation, portfolio oversight and business development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS Capital", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": investment structuring, financing solutions and capital mobilisation."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS Holdings", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": shareholdings, strategic assets and portfolio governance."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis Integrated Resources", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": integrated investment and enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis & Partners", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": partnership and project development."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The sector mandate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio spans essential systems and the capabilities that make them work: oil and gas; agriculture and agribusiness; telecommunications; banking and financial services; insurance; information technology; cement and building materials; media and communications; real estate, construction, facility management and retail; healthcare, pharmaceuticals and services; mining and quarrying; education and vocational training; sports and recreation; investments; and foundation and social development."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each principle below links portfolio breadth to disciplined execution and long-term value creation."}]}]}, "principles": [{"heading": "Diversification", "text": "Spread capital across strategic sectors to reduce risk."}, {"heading": "Value chain", "text": "Develop integrated assets that enhance portfolio synergies."}, {"heading": "Partnerships", "text": "Forge strategic alliances to access capabilities and markets."}, {"heading": "Governance", "text": "Apply commercial discipline through robust oversight."}]}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$Investment Philosophy · VECTIS$v$),
  seo_description = coalesce(seo_description, $v$Fifteen sectors, one disciplined investment mandate. Four principles guide how VECTIS deploys capital.$v$),
  status = $v$published$v$
where page_key = $v$investment-philosophy$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "Governance turns ambition into accountable execution. At VECTIS, an accountability loop connects investment decisions to operating performance.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The governance framework"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Group Board and Executive Management"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Investment and Risk Committee"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Finance and Treasury"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Legal and Regulatory Compliance"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Audit and Internal Controls"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Environmental and Social Governance"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The accountability loop"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Decisions move through a continuous loop: from the "}, {"type": "text", "text": "Board and Executive", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", through "}, {"type": "text", "text": "Investment and Risk", "marks": [{"type": "bold"}]}, {"type": "text", "text": " review and "}, {"type": "text", "text": "Finance and Treasury", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", to "}, {"type": "text", "text": "Compliance and Audit", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", and back to the Board, so that every investment is followed through to its results."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Governance is also one of the four principles that guide how VECTIS deploys capital: applying commercial discipline through robust oversight."}]}]}}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$Governance · VECTIS$v$),
  seo_description = coalesce(seo_description, $v$How VECTIS turns ambition into accountable execution, from investment decisions to operating performance.$v$),
  status = $v$published$v$
where page_key = $v$governance$v$ and is_system and content = $v${}$v$::jsonb;
update public.pages set content = $v${"intro": "VECTIS engages a broad range of partners across its investment platforms and operating clusters. For partnership, investment or general enquiries, please send us a message.", "form_success_message": "Thank you for contacting VECTIS. Your message has been received, and the appropriate team will respond."}$v$::jsonb,
  seo_title = coalesce(seo_title, $v$Contact VECTIS$v$),
  seo_description = coalesce(seo_description, $v$Get in touch with VECTIS about partnerships, investment and general enquiries.$v$),
  status = $v$published$v$
where page_key = $v$contact$v$ and is_system and content = $v${}$v$::jsonb;

-- An extra page for the VECTIS Foundation (/foundation).
insert into public.pages (page_key, template, title, slug, is_system, content, seo_title, seo_description, status)
values ($v$foundation$v$, $v$standard$v$, $v$VECTIS Foundation$v$, $v$foundation$v$, false, $v${"intro": "The VECTIS Foundation extends enterprise into community impact.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where the Foundation works"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Agricultural livelihoods", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and rural economic development"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Education", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", scholarships and vocational training"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Healthcare access", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and community health initiatives"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Youth employment", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", entrepreneurship and skills development"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sports and recreation", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", and support for vulnerable communities"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Foundation and social development is one of the fifteen sectors in the VECTIS investment mandate, completing a value chain that runs from capital to lasting impact."}]}]}}$v$::jsonb, $v$VECTIS Foundation$v$, $v$The VECTIS Foundation extends enterprise into community impact: livelihoods, education, health, youth and sport.$v$, $v$published$v$)
on conflict do nothing;

